#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using Object=UnityEngine.Object;
namespace Maze.EditorTools {
 public static partial class BlueUiProof {
  static LivingEnvironmentView living;static Vector3[] livePositions;static Quaternion[] liveRotations;static bool softBefore,objectsBefore;static string gridBefore;static Dictionary<Transform,Quaternion> bases;static Dictionary<Transform,Vector3> leaves;static Quaternion? barrelBefore;static bool liveMoved;static readonly HashSet<string> seenProps=new();
  static void DebugProp(string name,object value){var f=typeof(CryoPropMotion).GetField(name,System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static);Require(f!=null,"Required prop verification hook missing: "+name);f.SetValue(null,value);}
  static MonoBehaviour[] PropActors()=>Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).Where(p=>p.GetType().Name is "CryoPropMotion" or "CryoHeroTurret").ToArray();
  static Transform[] Animated(LivingEnvironmentView v)=>v.World.GetComponentsInChildren<Transform>().Where(t=>(t.name.StartsWith("HoloIsland")&&!t.name.Contains(" "))||t.name=="ServiceShoulder").ToArray();
  static void RoomState(string context,bool armory){
   living=Object.FindObjectsByType<LivingEnvironmentView>(FindObjectsInactive.Include,FindObjectsSortMode.None).FirstOrDefault(v=>v.IsArmory==armory&&v.Rendering);Require(living!=null,context+" active live view missing");
   Check(!living.PreviewCamera.orthographic,context+" renders actual perspective geometry");Check(living.PreviewCamera.targetTexture!=null&&living.PreviewCamera.targetTexture.width<=1920,context+" has a bounded live render target");
   Check(!living.GetComponent<UnityEngine.UI.RawImage>().raycastTarget,context+" backdrop cannot intercept retained controls");Check(living.World.GetComponentsInChildren<Transform>(true).All(t=>t.gameObject.layer==29),context+" isolated geometry uses only its dedicated layer");
   Check(living.World.GetComponentsInChildren<AudioListener>().Length==0&&living.World.GetComponentsInChildren<Collider>().Length==0,context+" scenery adds no audio listeners or gameplay collision");
   Check(RenderSettings.sun==null||RenderSettings.sun.name!="Room soft key",context+" camera restored the original scene sun");
   Check(living.World.GetComponentsInChildren<Renderer>().Any(r=>r.enabled&&r.name.Contains("Heavy frozen stance")),context+" uses the approved actual Heavy geometry");var body=LivingEnvironmentView.BoundsOf(living.World.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.name.Contains("Heavy frozen stance")));Check(Mathf.Abs(body.size.y-(armory?4.65f:4.15f))<.20f,context+" posed Heavy preserves the approved preview height ("+body.size.y.ToString("F3")+")");Check(Mathf.Abs(body.min.y-living.World.position.y)<.045f,context+" posed Heavy feet remain grounded");
   int count=living.World.GetComponentsInChildren<Renderer>().Count(r=>r.enabled);Check(count<110,context+" static room geometry is batched ("+count+" enabled renderers)");
   if(!armory)foreach(var id in LivingEnvironmentView.MappedZoneIds){var zone=SectorDefs.Get(id);var label=living.World.GetComponentsInChildren<TMPro.TMP_Text>().FirstOrDefault(t=>t.name=="MapZoneLabel_"+id);Check(zone!=null&&label!=null&&label.text==zone.name,"map-table miniature uses actual zone ID and name: "+id);}
   var nodes=Animated(living);Check(nodes.Length>0,context+" has separate articulated ambient nodes");liveMoved=false;livePositions=nodes.Select(t=>t.localPosition).ToArray();liveRotations=nodes.Select(t=>t.localRotation).ToArray();
  }
  static void RoomMotion(string context){var nodes=Animated(living);liveMoved|=nodes.Where((t,i)=>Vector3.Distance(t.localPosition,livePositions[i])>.0001f||Mathf.Abs(t.localRotation.x-liveRotations[i].x)+Mathf.Abs(t.localRotation.y-liveRotations[i].y)+Mathf.Abs(t.localRotation.z-liveRotations[i].z)+Mathf.Abs(t.localRotation.w-liveRotations[i].w)>1e-6f).Any();Check(liveMoved,context+" changes real transforms between frames");Check(nodes.Select((t,i)=>Vector3.Distance(t.localPosition,livePositions[i])).All(x=>x<.06f),context+" ambient translation stays restrained");Check(nodes.Select((t,i)=>Quaternion.Angle(t.localRotation,liveRotations[i])).All(x=>x<3),context+" ambient rotation stays restrained");}
  static void PrefabProps(){foreach(string slug in new[]{"cryo-pod","cryo-cooling-reactor","cryo-coolant-pumping-station","cryo-low-coolant-tank","cryo-supply-crate","cryo-freeze-canister","cryo-maintenance-cart","cryo-blast-door","cryo-gun-turret","cryo-flamethrower-turret"}){
   var src=Resources.Load<GameObject>("CryoProps/"+slug);Check(src!=null,slug+" optimized model imports as a usable prefab");if(src==null)continue;var go=Object.Instantiate(src);var rs=go.GetComponentsInChildren<Renderer>();var b=LivingEnvironmentView.BoundsOf(rs);Check(b.size.y>.4f&&b.size.y<4.7f,slug+" has plausible metre-scale height "+b.size.y.ToString("F3"));Check(Mathf.Abs(b.min.y)<.03f,slug+" root is grounded within 3 cm");
   Check(Resources.Load<Texture2D>("CryoProps/"+slug+"_base")!=null&&Resources.Load<Texture2D>("CryoProps/"+slug+"_normal")!=null,slug+" retains real albedo and normal textures");
   long tris=go.GetComponentsInChildren<MeshFilter>().Sum(m=>Enumerable.Range(0,m.sharedMesh.subMeshCount).Sum(n=>(long)m.sharedMesh.GetIndexCount(n)/3));Check(tris>1000&&tris<=31000,slug+" uses the delivered phone geometry ("+tris+" triangles)");
   if(slug.Contains("turret")){var names=go.GetComponentsInChildren<Transform>().Select(t=>t.name);Check(new[]{"base","yaw_head","pitch_assembly"}.All(names.Contains),slug+" retains independent base, yaw and pitch");if(slug.Contains("gun-turret"))Check(names.Contains("barrel_cluster"),"gun turret retains independent barrel cluster");}
   Object.DestroyImmediate(go);
  }}
  static string GridSignature()=>string.Join("",Enumerable.Range(0,MazeMap.H).SelectMany(z=>Enumerable.Range(0,MazeMap.W).Select(x=>MazeMap.grid[z,x])).ToArray());
  static void SpawnedProps(int floor){ValidateRoomDataAndBarrels(floor);var props=PropActors();Check(props.Length>0,"Cryo floor "+floor+" instantiates optimized props");foreach(var p in props){
   foreach(var r in p.GetComponentsInChildren<Renderer>())foreach(var m in r.sharedMaterials){Check(m!=null&&m.shader.name=="Maze/CryoSoftSurface","floor "+floor+" "+p.name+" uses the room's material shader");if(m!=null&&m.name.StartsWith("Prop_cryo")){seenProps.Add(m.name.Substring(5));Check(m.GetTexture("_BaseMap")!=null&&m.GetTexture("_BumpMap")!=null,p.name+" has real albedo and normal maps bound");}}
   if(p.GetComponentsInChildren<Transform>().Any(t=>t.name=="leaf_left"))continue;var point=p.transform.position;int x=Mathf.FloorToInt(point.x/MazeMap.C),z=Mathf.FloorToInt(-point.z/MazeMap.C);Check(!MazeMap.Walkable(x,z),"floor "+floor+" "+p.name+" is anchored on existing solid map footprint");
  }}
  static void ValidateRoomDataAndBarrels(int floor){
   var roomRoot=Object.FindAnyObjectByType<CryoSoftSceneInfo>();
   if(roomRoot!=null){
    Check(roomRoot.GetComponentsInChildren<Collider>().Length==0,"floor "+floor+" authored map visuals add no physical colliders");
    var blocked=MazeMap.Rects(c=>c=='r').Select(r=>new Rect(r.x*2,-(r.y+r.height)*2,r.width*2,r.height*2)).ToArray();
    var rails=roomRoot.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("SC_rail")).ToArray();
    bool contained=rails.All(f=>f.sharedMesh.vertices.All(v0=>{var v=f.transform.TransformPoint(v0);return blocked.Any(r=>v.x>=r.xMin-.003f&&v.x<=r.xMax+.003f&&v.z>=r.yMin-.003f&&v.z<=r.yMax+.003f);}));
    Check(contained,"floor "+floor+" broad low cover remains inside the original blocked grid footprint");
   }

   var data=Object.FindObjectsByType<CryoSoftRoomData>(FindObjectsSortMode.None).FirstOrDefault();Check(data!=null&&data.ao!=null,"floor "+floor+" retains serialized room contact data and texture");
   if(data!=null){var layout=ZoneData.Layouts[MazeMap.LayoutName(MazeMap.MapIndex)];Check(data.size==new Vector2(layout[0].Length*2,layout.Length*2),"room contact map covers the exact authored layout size");}
   var barrels=Object.FindAnyObjectByType<Barrels>();Check(barrels!=null&&barrels.list.Count>0,"Cryo room retains its real explosive barrels");
   if(barrels==null)return;foreach(var b in barrels.list){Check(b.rends.All(r=>r.sharedMaterials.All(m=>m.shader.name=="Maze/PolishPaint")),"Cryo barrel uses one coherent painted visual");Check(b.tr.GetComponentsInChildren<Collider>().Length==0,"painted barrel adds no collider or gameplay footprint");var bounds=LivingEnvironmentView.BoundsOf(b.rends);Check(Mathf.Abs(bounds.size.y-G.cfg.barrels.height)<.04f,"painted barrel retains the configured production height");Check(barrels.At(b.p)==b,"existing barrel collision query resolves its unchanged logical position");}
  }
  static void PrepareArticulation(){bases=new();leaves=new();barrelBefore=null;foreach(var p in PropActors())foreach(var t in p.GetComponentsInChildren<Transform>()){if(t.name=="base")bases[t]=t.localRotation;if(t.name.StartsWith("leaf_"))leaves[t]=t.localPosition;if(t.name=="barrel_cluster")barrelBefore=t.localRotation;}DebugProp("DebugTarget",(Vector3?)(G.player.transform.position+new Vector3(5,2,4)));DebugProp("DebugOpen",true);}
  static void CheckArticulation(){Check(bases.Count>=2,"first Cryo scene contains both turret bases");Check(bases.All(x=>Quaternion.Angle(x.Key.localRotation,x.Value)<.01f),"turret tracking leaves fixed bases unchanged");foreach(var t in bases.Keys){var yaw=t.GetComponentsInChildren<Transform>().FirstOrDefault(x=>x.name=="yaw_head");var pitch=t.GetComponentsInChildren<Transform>().FirstOrDefault(x=>x.name=="pitch_assembly");Check(yaw!=null&&pitch!=null,"turret yaw and pitch remain attached");if(yaw!=null)Check(Quaternion.Angle(yaw.localRotation,Quaternion.identity)>1,"turret yaw responds to a target");if(pitch!=null)Check(Quaternion.Angle(pitch.localRotation,Quaternion.identity)<=35.1f,"turret pitch stays within its mechanical envelope");}
   var barrel=PropActors().SelectMany(p=>p.GetComponentsInChildren<Transform>()).FirstOrDefault(t=>t.name=="barrel_cluster");if(barrel!=null&&barrelBefore.HasValue)Check(Quaternion.Angle(barrel.localRotation,barrelBefore.Value)>1,"gun barrel cluster spins independently while locked");Check(leaves.Count==2&&leaves.All(x=>Mathf.Abs(x.Key.localPosition.x-x.Value.x)>.36f),"blast door leaves slide outward into their pockets");DebugProp("DebugOpen",false);DebugProp("DebugTarget",null);
  }
  static void AddLivingSteps(Vector2Int size){
   Add(()=>{MenuTitle(size);PrefabProps();Wait(.7);});Add(()=>{Click(Title.PlayButton);Wait(.8);});
   Add(()=>{StaticHangarState();CaptureScreen("living_hangar");Wait(1);});Add(()=>{StaticHangarState();CaptureScreen("living_hangar_retained");Click(P.GearButton);Gear.ChooseFilter(-1);Wait(.8);});
   Add(()=>{RoomState("Armory",true);Gear.ChooseFilter(-1);CaptureScreen("living_equipment");Wait(1);});Add(()=>{RoomMotion("Armory");CaptureScreen("living_equipment_motion");CloseGear();softBefore=CryoSoftEnvironment.Enabled;objectsBefore=CryoSoftEnvironment.Objects;CryoSoftEnvironment.Enabled=true;CryoSoftEnvironment.Objects=true;seenProps.Clear();StartRun(size);Wait(1.8);});
   Add(()=>{Check(Object.FindObjectsByType<LivingEnvironmentView>(FindObjectsInactive.Include,FindObjectsSortMode.None).All(v=>!v.Rendering),"all living menu cameras stop rendering during gameplay");SpawnedProps(1);gridBefore=GridSignature();CaptureScreen("living_cryo_floor1");PrepareArticulation();Wait(1.8);});
   Add(()=>{CheckArticulation();CaptureScreen("living_cryo_articulation");Wait(1.5);});Add(()=>{Check(leaves.All(x=>Vector3.Distance(x.Key.localPosition,x.Value)<.01f),"blast door leaves return to their closed pivots");CryoSoftEnvironment.Objects=false;G.DebugFloor(1);G.events.Tick(0);G.Tick(0);Check(GridSignature()==gridBefore,"adding or removing prop visuals preserves the exact first-floor collision grid");CryoSoftEnvironment.Objects=true;Wait(.4);});
   foreach(int floor in new[]{2,3,4,5}){int f=floor;Add(()=>{G.DebugFloor(f);G.events.Tick(0);G.Tick(0);Wait(.7);});Add(()=>{SpawnedProps(f);});}
   Add(()=>{foreach(var slug in new[]{"cryo-pod","cryo-cooling-reactor","cryo-coolant-pumping-station","cryo-low-coolant-tank","cryo-supply-crate","cryo-freeze-canister","cryo-maintenance-cart","cryo-blast-door","cryo-gun-turret","cryo-flamethrower-turret"})Check(seenProps.Contains(slug),"actual Cryo floor scenes include "+slug);G.ToMenu();CryoSoftEnvironment.Enabled=softBefore;CryoSoftEnvironment.Objects=objectsBefore;DebugProp("DebugOpen",false);DebugProp("DebugTarget",null);Wait(.5);});
  }
 }
}
#endif
